const crypto = require('crypto');
const base = String($env.ODOO_PROD_ORCH_BASE_URL || 'https://drpaws.ai').replace(/\/$/, '');
const secret = String($env.ODOO_ORCH_WEBHOOK_SECRET_PROD || $env.ODOO_ORCH_WEBHOOK_SECRET || '');
if (!base || !secret) throw new Error('missing_odoo_prod_discovery_env');
const bodyObj = { try_canary: true, source: 'n8n-direct-ats-hunter' };
const raw = Buffer.from(JSON.stringify(bodyObj));
const ts = Math.floor(Date.now()/1000).toString();
const sig = crypto.createHmac('sha256', secret).update(ts + '.').update(raw).digest('hex');
return [{
  json: {
    url: `${base}/linkedin/orchestrator/v1/discovery/run`,
    status_url: `${base}/linkedin/orchestrator/v1/discovery/status`,
    body: bodyObj,
    raw: raw.toString(),
    ts,
    signature: `sha256=${sig}`
  }
}];

const crypto = require('crypto');
const prev = $('Sign Discovery Run').first().json;
const run = $input.first().json;
const secret = String($env.ODOO_ORCH_WEBHOOK_SECRET_PROD || $env.ODOO_ORCH_WEBHOOK_SECRET || '');
const raw = Buffer.from('');
const ts = Math.floor(Date.now()/1000).toString();
const sig = crypto.createHmac('sha256', secret).update(ts + '.').update(raw).digest('hex');
return [{
  json: {
    run,
    status_url: prev.status_url,
    ts,
    signature: `sha256=${sig}`
  }
}];

const runWrap = $('Sign Status GET').first().json.run || {};
const run = runWrap.data || runWrap;
const status = $input.first().json;
const canary = (run.data && run.data.canary) || run.canary || {};
const operating = (status.data && status.data.operating_state) || run.operating_state || 'ATS_DISCOVERY_LIVE_WAITING_FOR_SAFE_CANARY';
const out = {
  ok: true,
  operating_state: operating,
  account1_apps: (status.data && status.data.account1_apps) || 0,
  safe_canary_jobs: (status.data && status.data.safe_canary_jobs) || 0,
  stats: (run.data && run.data.stats) || run.stats || {},
  canary,
  activate_submit_workflow: !!(canary && canary.activate_n8n),
  submit_workflow_id: String($env.N8N_JOB_ORCH_SUBMIT_WORKFLOW_ID || '5X4dygwEwzNPalNc'),
  note: 'Discovery never submits without safe canary gates. CAPTCHA is never bypassed.'
};
if (out.account1_apps !== 0) throw new Error('company_account_isolation_broken');
return [{ json: out }];
